import os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()
import re
def parse(label):
    m=re.search(label+r' \((\d+)x(\d+)\):\n',t)
    h,w=int(m[1]),int(m[2])
    return [[int(x) for x in r.split()] for r in t[m.end():].split('\n')[:h]]
din,dout=parse('Demo pair 1 input'),parse('Demo pair 1 output')
test=parse('Test input')

def transform(g):
    n=len(g); out=[row[:] for row in g]
    blocks=[(r,c) for r in range(n-1) for c in range(n-1)
            if g[r][c]==2 and g[r][c+1]==2 and g[r+1][c]==2 and g[r+1][c+1]==2]
    for (r0,c0) in blocks:
        pos={'TL':(r0-1,c0-1),'TR':(r0-1,c0+2),'BL':(r0+2,c0-1),'BR':(r0+2,c0+2)}
        old={k:g[p[0]][p[1]] for k,p in pos.items()}
        new={'TL':old['BL'],'TR':old['TL'],'BR':old['TR'],'BL':old['BR']}
        dirs={'TL':(-1,-1),'TR':(-1,1),'BL':(1,-1),'BR':(1,1)}
        for k,p in pos.items():
            r,c=p; dr,dc=dirs[k]; col=new[k]
            while 0<=r<n and 0<=c<n:
                out[r][c]=col; r+=dr; c+=dc
    return out

r=transform(din)
print(r==dout)
print(transform(test))

